//! Every emoji: its glyph, name, Unicode CLDR group and search keywords, in
//! the order Unicode's emoji-test lists them, and the search over them.
//! Shared by the Command Center's emoji page and the Control Center
//! launcher's.
//!
//! The table ([`EMOJIS`]) is generated by
//! `lntrn-command-center/scripts/setup-emojis.py`: re-run it after a
//! Unicode or Noto update rather than editing it by hand.

mod data;

pub use data::{EMOJIS, EmojiEntry};

/// Top-level emoji groupings (Unicode CLDR groups).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Category {
    Smileys,
    People,
    AnimalsNature,
    FoodDrink,
    Activities,
    TravelPlaces,
    Objects,
    Symbols,
    Flags,
}

impl Category {
    pub const ALL: [Category; 9] = [
        Category::Smileys,
        Category::People,
        Category::AnimalsNature,
        Category::FoodDrink,
        Category::Activities,
        Category::TravelPlaces,
        Category::Objects,
        Category::Symbols,
        Category::Flags,
    ];

    pub fn label(self) -> &'static str {
        match self {
            Category::Smileys => "Smileys & Emotion",
            Category::People => "People & Body",
            Category::AnimalsNature => "Animals & Nature",
            Category::FoodDrink => "Food & Drink",
            Category::Activities => "Activities",
            Category::TravelPlaces => "Travel & Places",
            Category::Objects => "Objects",
            Category::Symbols => "Symbols",
            Category::Flags => "Flags",
        }
    }

    /// Codepoint used as the visual tab icon for this category (its PNG's
    /// name in the Command Center's emoji pack).
    pub fn icon_unicode(self) -> &'static str {
        match self {
            Category::Smileys => "1f600",       // 😀
            Category::People => "1f44b",        // 👋
            Category::AnimalsNature => "1f436", // 🐶
            Category::FoodDrink => "1f355",     // 🍕
            Category::Activities => "26bd",     // ⚽
            Category::TravelPlaces => "1f697",  // 🚗
            Category::Objects => "1f4a1",       // 💡
            Category::Symbols => "1f4af",       // 💯
            Category::Flags => "1f1fa-1f1f8",   // 🇺🇸
        }
    }

    /// A glyph standing for the category, one of its own, for drawing as
    /// text (the launcher's sidebar). Not always [`Self::icon_unicode`]'s:
    /// 💯 is filed under Smileys & Emotion, and the table has no country
    /// flags.
    pub fn icon(self) -> &'static str {
        match self {
            Category::Smileys => "😀",
            Category::People => "👋",
            Category::AnimalsNature => "🐶",
            Category::FoodDrink => "🍕",
            Category::Activities => "⚽",
            Category::TravelPlaces => "🚗",
            Category::Objects => "💡",
            Category::Symbols => "🔣",
            Category::Flags => "🏁",
        }
    }
}

/// Indices into [`EMOJIS`], in its order: those whose name or one of whose
/// keywords holds `query` (whatever its case) when there is one, else all
/// of `category`'s.
pub fn visible(query: &str, category: Category) -> Vec<usize> {
    let needle = query.trim().to_lowercase();
    EMOJIS
        .iter()
        .enumerate()
        .filter(|(_, e)| {
            if needle.is_empty() {
                e.category == category
            } else {
                e.name.to_lowercase().contains(&needle) || e.keywords.iter().any(|k| k.to_lowercase().contains(&needle))
            }
        })
        .map(|(i, _)| i)
        .collect()
}

/// The index in [`EMOJIS`] of the emoji drawn as `glyph`.
pub fn position(glyph: &str) -> Option<usize> {
    EMOJIS.iter().position(|e| e.glyph == glyph)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_category_has_emoji_and_its_icon_is_one() {
        for c in Category::ALL {
            assert!(!visible("", c).is_empty(), "{c:?} is empty");
            assert!(position(c.icon()).is_some_and(|i| EMOJIS[i].category == c), "{c:?}'s icon isn't one of its own");
        }
    }

    #[test]
    fn the_search_reads_names_and_keywords_in_any_case() {
        let grinning = position("😀").expect("the grinning face");
        assert!(visible("grinning", Category::Flags).contains(&grinning), "by name, whatever the category");
        assert!(visible("  CHEERFUL ", Category::Flags).contains(&grinning), "by keyword, any case, trimmed");
        assert!(visible("no emoji is called this", Category::Smileys).is_empty());
        assert_eq!(visible("", Category::Smileys).first(), Some(&grinning), "a category in the table's order");
    }
}
